  "a_sentences": [
    {
      "a_text": "La reprise de contrat exige l'accord de toutes les parties concernées, contrairement à la cession qui peut être convenue sans le consentement ni la connaissance du débiteur cédé.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "L'employeur est la personne qui dispose du droit aux prestations du travailleur et qui est liée par le contrat de travail.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Dans un groupe, il faut déterminer au cas par cas quelle société revêt la qualité d'employeur, le volonté réelle des parties demeurant déterminante.",
      "b_propositions": ["P3", "P4"]
    },
    {
      "a_text": "La résiliation de l'emploi prévue au 31 décembre 2021 est nulle, faute de légitimation de l'intimée.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La question de savoir si cette nullité entraîne la nullité totale du contrat ou seulement partielle peut rester indécise.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le recours, dans la mesure de sa recevabilité.",
      "b_propositions": ["P8"]
    }
  ]
}
